function norm(v){return String(v||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]/g,'')}
function add(target,near){if(!Array.isArray(target))return;const counts=new Map();for(const r of target){if(String(r[1])!=='marche')continue;const k=[String(r[0]),norm(r[3]),norm(r[4])].join('|');counts.set(k,(counts.get(k)||0)+1)}const groups=new Map();for(const r of rows){const k=[String(r[0]),norm(r[3]),norm(r[4])].join('|');if(!groups.has(k))groups.set(k,[]);groups.get(k).push(r)}for(const [k,rs] of groups){let need=Math.max(0,rs.length-(counts.get(k)||0));for(let i=0;i<need;i++){const r=rs[i];target.push(near?[r[0],r[1],r[2],r[3],r[4],r[5],r[6],r[7],r[8],r[10],r[11],[r[3],r[2],r[8]].join(', '),r[12],r[13],'','','']:r)}}}
add(window.data,false);add(window.NEAR_FR,true);window.MARCHES_FRANCE_NATIONAL_COUNT=rows.length;
